    'Avanzado',
    'En el esquema se observa el cruce entre dos tipos de semillas (razas puras), una raza de semillas rojas y redondas (VVRR) y la otra de semillas verdes y moteadas (vvrr). El híbrido obtenido en la F1 (VvRr) origina 4 tipos de gametos, que al unirse originan 16 posibles combinaciones. Por tanto, se obtienen 4 tipos de semillas en la F2 en una proporción 9:3:3:1. ¿A qué se debe?',
    'Cada par de alelos que controla un carácter se transmite independientemente de cualquier otro par de alelos que controle otro carácter, porque los dos alelos que controlan cada carácter se separan durante la formación de gametos.',
    'Al cruzar dos variedades puras (Homocigóticas) para un carácter, todos los descendientes de la primera generación son heterocigóticos e idénticos entre sí, pues manifiestan el carácter dominante.',
    'El gen que regula la altura del tallo presenta dos alelos, uno que determina la semilla roja y otro que determina la semilla moteada.',
