    'La digestión es el proceso de transformación y absorción de los alimentos que son ingeridos por vía bucal. ¿Cómo se realiza tal proceso?',
    'La reacción química que se da en este proceso es la hidrólisis, y para ello se necesita de los jugos digestivos que contienen las enzimas responsables de estas transformaciones.',
    'Tiene lugar en el tubo digestivo y consiste en la masticación de los alimentos que se fragmentan y se mezclan con la saliva para formar el bolo alimenticio y los transforman en elementos asimilables: hidratos de glucosa; grasas, glicerina, y aminoácidos.',
    'Cuando el alimento entra en el órgano, las paredes se expanden y la cavidad aumenta sin que se produzcan cambios en la presión Intra gástrica.',
