    'Entorno_vivo',
    'Satisfactorio',
    'El arroz es un alimento cuyo consumo está muy extendido; constituye la base de la dieta de casi la mitad de los habitantes del mundo. Su producción enfrenta varios inconvenientes como las enfermedades graves propias del grano provocadas por hongos; las plagas: insectos, microorganismos, roedores, aves que ocasionan una pérdida entre el 40 y 50% de la producción. ¿Para combatir estos problemas lo más efectivo es?',
    'Aplicación de fungicidas, sustancias tóxicas que se emplean para impedir el crecimiento o para matar los hongos perjudiciales para las plantas, los animales o el hombre. La mayoría de los fungicidas de uso agrícola se fumigan o espolvorean sobre las semillas, hojas o frutas para impedir la propagación de la roya, el tizón, los mohos, o el mildiu.',
    'Aplicación de herbicidas de amplio espectro, como el glifosato, que controlan casi todas las formas de vegetación. Algunos esterilizan el suelo, eliminan toda la vegetación y retrasan la invasión de nuevas malas hierbas.',
    'Creación de virus artificiales que tengan como objetivo exclusivo ciertas larvas o plagas de insectos que al ser fumigados sobre los cultivos. Los virus, que son inofensivos para otras especies, se autodestruyen cuando su trabajo tóxico ha terminado.',
