    'En el estudio Tuskegee sobre sífilis no tratada en varones negros en Alabama (1932 - 1972), se utilizó una muestra de 399 varones pobres afroamericanos infectados y 201 sanos como control, en su mayoría analfabetos. Los participantes fueron engañados al decirles que tenían "mala sangre" y que podrían recibir tratamiento médico gratuito, transporte a la clínica, comidas y un seguro de sepelio en caso de fallecimiento, si participaban en el estudio. Después hacer pública esta investigación se generó un gran escándalo. Para brindar una solución al engaño se creó una comisión que explicó, identificó y unificó los principios éticos básicos en la experimentación con seres humanos. A raíz de estas nuevas disposiciones éticas, algunos investigadores se sintieron extremadamente limitados en sus posibilidades de hacer experimentación. ¿Cuál de los siguientes serían un efecto no esperado del establecimiento de regulaciones para las investigaciones?',
    'Que los experimentos respeten la autonomía de las personas.',
    'Que los experimentos tengan efectos negativos en la salud de las personas.',
    'Que los experimentos se hagan exclusivamente con los enfermos pobres.',
    'Que los experimentos se hagan disfrazando el propósito de la investigación.',
    'B',
