    'En un municipio arrocero del país hay una sequía que está afectando seriamente la cosecha de este año. A 20 kilómetros del municipio hay una represa creada para generar energía eléctrica para la región. Los habitantes del municipio le piden al gobierno departamental que deje desviar agua de la represa para que los cultivos de arroz no se dañen. El gobierno departamental niega la solicitud porque dice que el propósito de la represa es producir energía eléctrica para toda la región. ¿Cuáles de las siguientes dimensiones están presentes en este caso?',
