    'En el país se presentan nuevas circunstancias políticas que hacen necesaria una reforma a la Constitución. Los ministros dicen que por ser urgente, la reforma la puede hacer el Presidente. Los congresistas dicen que la reforma debe hacerla el Congreso. Según la Constitución, ¿tienen razón los congresistas?',
