    'Competencias_ciudadanas',
    'Avanzado',
    'El gobierno de un país hizo estudios en el subsuelo de una región rural poco habitada, los cuales concluyen que existe una gran riqueza mineral del lugar. En consecuencia, la minería a gran escala aparece como una importante fuente de ganancias, dados los precios altos en el mercado mundial. El gobierno considera que debe impulsar esta forma de hacer minería, aunque implique una inversión en maquinaria y tecnología especializada, que sólo mano de obra calificada puede operar. Los pobladores de la región se oponen al proyecto minero, ya que además del alto impacto ambiental, les preocupa la gran cantidad de terrenos que se necesitarían para llevarlo a cabo. Ante este panorama, es posible que se presente un conflicto. ¿Cuál sería la causa?',
    'El gobierno quiere favorecer intereses económicos de unos pocos en detrimento del bienestar de la mayoría.',
    'Los habitantes de la región no quieren compartir los recursos que pueden favorecer a toda la población del país y no solo a una región.',
    'El progreso económico y tecnológico implica algunos sacrificios de la población de una región inviable económicamente.',
    'El proyecto del gobierno puede traer beneficios en crecimiento económico, pero podría generar problemas sociales como el desempleo y el desplazamiento.',
