    'Un joven universitario decidió que nunca va a votar porque piensa que todos los políticos son corruptos y que el sistema democrático no funciona. Dice que prefiere no saber qué está pasando en el país ni en su comunidad, porque, de todos modos, no se solucionan los problemas. Con esta actitud, el joven desconoce sus deberes como ciudadano, porque',
