(
    'a2f5a345-fabc-4d0b-8228-d50b2aec97dc',
    'General',
    'Interpretación y análisis de perspectivas',
    'Competencias_ciudadanas',
    'Avanzado',
    'En la última década se ha agudizado en América Latina la "biopiratería". Esto es, el acceso, uso y aprovechamiento de las riquezas biológicas (animales o plantas) y de los conocimientos tradicionales de comunidades indígenas, por empresas privadas, originarias en su mayoría de países desarrollados. Así, muchos recursos han pasado a ser parte de los inventarios protegidos legalmente por patentes o derechos de propiedad intelectual de varios países desarrollados, sin el reconocimiento de sus lugares de origen ni el pago a estos por los beneficios obtenidos. Por otra parte, ha surgido un movimiento internacional (AM) que busca que estos recursos sean declarados como patrimonio de la humanidad y que, por tanto, puedan ser aprovechados por cualquier persona, independiente de su nacionalidad. Por su parte, movimientos indígenas latinoamericanos buscan la aprobación de leyes que frenen este fenómeno, que han llamado "la segunda colonización". En la situación descrita, probablemente se presente un choque de intereses entre',
    'los líderes de los países latinoamericanos y los líderes de los países desarrollados, con respecto a quién es responsable de la protección de las riquezas biológicas.',
    'los defensores de los conocimientos tradicionales indígenas y quienes defienden la idea de que los recursos son de libre aprovechamiento.',
    'los gobiernos latinoamericanos y las comunidades indígenas por la distribución equitativa de las ganancias obtenidas con las ventas de los recursos biológicos.',
    'las empresas privadas de países desarrollados y los líderes de AM por el libre aprovechamiento de los recursos biológicos.',
    'B',
    NULL,
    NULL,
    false,
    0.407,
    1.184,
    0.173
),
