    'Competencias_ciudadanas',
    'Satisfactorio',
    'Una ciudadana, ejerciendo el derecho a la libertad de opinión, se ha manifestado públicamente en contra de la adopción de niños por parte de parejas conformadas por personas del mismo sexo. Ella sostiene que el Estado no debe permitir estas adopciones, afirmando lo siguiente: "Lo que sí existe es el derecho de los niños a ser protegidos y criados por una familia y, en el caso de los niños desamparados, sin familia, el Estado está en la obligación de garantizarles este derecho de la mejor manera posible." El fragmento anterior contiene un prejuicio que no está explícitamente justificado. ¿Cuál es?',
