    '9d43adf0-2048-4bec-aa86-477b61ec3aa7',
    'General',
    'Interpretación y análisis de perspectivas',
    'Competencias_ciudadanas',
    'Satisfactorio',
    'En el año 2006, el Gobierno colombiano decidió dejar de controlar los precios de los medicamentos. Libres de regulación estatal, los laboratorios multinacionales aumentaron los precios, a tal punto que llegaron a ser los más altos de Latinoamérica. Incluso algunos productos para la diabetes llegaron a tener los precios más altos del planeta. Recientemente, el Ministerio de Salud de ese país decidió declarar de "interés público" un medicamento vital para el tratamiento de la leucemia llamado Leuce. La decisión implica que otros laboratorios (incluso nacionales) diferentes a la multinacional que tiene la patente, podrán producir el medicamento y venderlo como genérico a un precio menor que el ofrecido por la multinacional. Al declarar de "interés público" al Leuce, el gobierno beneficia a',
