    'Satisfactorio',
    'El alcalde de un municipio, su abogado asesor y el que es considerado el mayor contratista de la región compraron, por $244 millones, 129.881 m2 de tierra en dos veredas de ese municipio. Gracias a unos $4.700 millones de recursos nacionales y municipales que el mandatario destinó a rieles, pavimentos e iluminación de vías, el precio de ese pedazo de tierra comprado puede superar hoy los $12.000 millones. La situación ha sido conocida por diferentes personas quienes denunciaron que después de comprar esas propiedades, el alcalde incluyó dentro del Plan Básico de Ordenamiento Territorial (PBOT) del municipio, inversiones en vías e iluminación que no estaban en el Plan de Desarrollo que fue presentado al inicio del mandato, pero que sí favorecían la valorización de esos predios rurales. Consultado sobre esa denuncia, el alcalde reconoció que los beneficios no son solo para él y sus allegados, sino para toda la comunidad. De acuerdo con el texto anterior, los señalamientos en contra del alcalde obedecen a que los denunciantes',
