    '95eb527c-fbe9-4b72-9cf2-771ae91b7116',
    'General',
    'Interpretación y análisis de perspectivas',
    'Historia',
    'Avanzado',
    'Considere el siguiente fragmento extraído de un Plan nacional de desarrollo de México: "La productividad no sólo se incrementa con las grandes reformas estructurales. El proceso de crecimiento del país también se puede y debe impulsar desde los sectores privado, social y desde todos los órdenes de gobierno. En este sentido, esta estrategia plantea que la Administración Pública Federal busque el incremento de la productividad mediante la eliminación de trabas que impiden el funcionamiento adecuado de la economía, promoviendo la creación de empleos, mejorando la regulación y, de manera especial, simplificando la normatividad y trámites gubernamentales". ¿Con cuál de los siguientes modelos es afín esta propuesta para mejorar la productividad económica?',
