    '0.52',
    'Los chinos y los japoneses propusieron en la antigüedad una explicación para los sismos y la actividad volcánica que denominaron la "explicación sintética". Esta teoría señalaba que estos fenómenos son originados por el Gran Dragón que habitaba en el interior de la Tierra, el cual cuando estaba molesto sacudía su rugosa piel o, peor aún, arrojaba fuego por sus narices. Esta explicación no científica se puede entender porque estas culturas',
    'asumían que los fenómenos de la naturaleza respondían a los dioses, definiendo así las alteraciones y modificaciones ambientales.',
