    'El gobierno decidió construir una represa que es indispensable para generar electricidad para todo el país. La represa sólo puede construirse en un sitio en el que hay un asentamiento indígena. En principio, al hacer las consultas respectivas con esta comunidad, ellos se negaban a la construcción de la represa. Sin embargo, después de un largo proceso de conciliación con la comunidad, se acordó la construcción de la represa y que los indígenas se asentaran en otro territorio. Según la Constitución política de Colombia, en esta situación el gobierno',
